// Flatten taxonomy into a lookup-friendly structure
function flattenTaxonomy() {
  const flat = [];
  for (const [domain, domainData] of Object.entries(TAXONOMY)) {
    for (const [intent, intentData] of Object.entries(domainData.intents)) {
      flat.push({
        domain,
        domainLabel: domainData.label,
        intent,
        intentLabel: intentData.label,
        fullKey: `${domain}.${intent}`,
        exemplars: intentData.exemplars
      });
    }
  }
  return flat;
}

module.exports = { TAXONOMY, flattenTaxonomy };
